items.question_latex:
\section*{Məsələnin Şərti}
Tənliyin ümumi həllini və verilmiş başlanğıc şərtini ödəyən xüsusi həllini tapın:
\[(x + 2y)y' = 1, \quad y(0) = 1\]

items.code_snippet:
% Birinci tərtib xətti qeyri-bircins ODE: dy/dt + y = 2t, y(0) = 1
f = @(t, y) -y + 2*t;
[t, y] = ode45(f, [0 5], 1);

figure;
plot(t, y, 'LineWidth', 2, 'Color', [0.15 0.45 0.75]);
hold on;
grid on;
xlabel('t'); ylabel('y(t)');
title('ode45 Həlli: dy/dt = -y + 2t');

#include <iostream>
#include <cmath>
#include <iomanip>

double f(double x)  { return x * x - 2.0; }
double df(double x) { return 2.0 * x; }

int main() {
    double x = 1.0;
    const double eps = 1e-9;
    for (int i = 0; i < 20; ++i) {
        double next = x - f(x) / df(x);
        if (std::abs(next - x) < eps) break;
        x = next;
    }
    std::cout << std::fixed << std::setprecision(10) << "sqrt(2) approx: " << x << "\n";
    return 0;
}
